mapper.select:
SELECT id, kind, word, built_in, created_by, created_at FROM content_word
kind = #{kind}
ORDER BY kind, id

mapper.update:
UPDATE content_template SET title_en = #{titleEn}, title_zh_cn = #{titleZhCn}, title_zh_tw = #{titleZhTw}, rules_en = #{rulesEn},
  rules_zh_cn = #{rulesZhCn}, rules_zh_tw = #{rulesZhTw}, options = #{options}, source_primary = #{sourcePrimary}, source_backup = #{sourceBackup},
  version = version + 1, updated_by = #{updatedBy}, updated_at = #{updatedAt}
WHERE code = #{code} AND version = #{version}

