UPDATE content_page SET
intro_en = #{intro}, intro_zh_cn = #{intro}, intro_zh_tw = #{introTw},
updated_at = #{now} WHERE id = #{id}

UPDATE content_page SET
title_en = #{title}, body_en = #{body}, title_zh_cn = #{title}, title_zh_tw = #{titleTw}, body_zh_cn = #{body}, body_zh_tw = #{bodyTw},
updated_at = #{now} WHERE id = #{id}

UPDATE content_ai_day SET used = used + 1,
  score_used = score_used + 1content_used = content_used + 1
WHERE day = #{day} AND used < #{cap}
